"use strict";(globalThis.webpackChunkgrc||=[]).push([[41937],{85508(e){e.exports=JSON.parse('{"citeKey":"kougkas2017rethinkingkey","slug":"kougkas-2017-rethinking-key-02de","title":"Rethinking Key Value Store for Parallel I/O Optimization","authors":["A. Kougkas","H. Eslami","R. Thakur","W. D. Gropp","X.-H. Sun"],"venue":"International Journal of High Performance Applications,2017. vol. 31, no. 4, pp. 335-356","type":"Journal","entryType":"article","date":"July, 2017","year":2017,"era":"iit","month":7,"doi":"10.1177/1094342016677084","abstract":"Key-value stores are being widely used as the storage system for large-scale internet services and cloud storage systems. However, they are rarely used in HPC systems, where parallel file systems are the dominant storage solution. In this study, we examine the architecture differences and performance characteristics of parallel file systems and key-value stores. We propose using key-value stores to optimize overall Input/Output (I/O) performance, especially for workloads that parallel file systems cannot handle well, such as the cases with intense data synchronization or heavy metadata oper- ations. We conducted experiments with several synthetic benchmarks, an I/O benchmark, and a real application. We modeled the performance of these two systems using collected data from our experiments, and we provide a predictive method to identify which system offers better I/O performance given a specific workload. The results show that we can optimize the I/O performance in HPC systems by utilizing key-value stores.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2017/kougkas-2017-rethinking-key-02de.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["kougkas-anthony","sun-xian-he"]}')}}]);